fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"

    return if (exposureTimeNs >= 1_000_000_000L) {

        val seconds = exposureTimeNs / 1_000_000_000.0
        if (seconds % 1.0 < 0.05 || seconds % 1.0 > 0.95) {
            "${seconds.roundToInt()}s"
        } else {

            String.format(java.util.Locale.US, "%.1fs", seconds)
        }
    } else {

        val denominator = (1_000_000_000.0 / exposureTimeNs).roundToInt().coerceAtLeast(1)
        "1/${denominator}s"
    }
}

